#include "stdafx.h"#include "SOEtransport.h"#include <rsuMemoryManager.h>#ifdef _MANAGED#pragma managed(push, off)#endifKRsuMemoryManager g_SOEmemory;BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){  switch (ul_reason_for_call)  {  case DLL_PROCESS_ATTACH:    g_SOEmemory.Create( "SOE_Mem", 3 );  case DLL_THREAD_ATTACH:  case DLL_THREAD_DETACH:  case DLL_PROCESS_DETACH:    break;  }  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endifextern "C" __declspec(dllexport) IBaseModel* CreateObject(LPCTSTR ObjName, IBaseModel * pParent, int SubObjType ){  return new KSOEtransport( (char*)ObjName );}